/*selectSellerMpRqBulkQuotationReq*/ SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ04' AND CODE = STATUS) AS STATUS, AGENT_TYPE_NAME, BURQ_RFQ_NO, PROJECT_NAME, BUYER_NAME, ATOS_DATE, ATOS_END_DATE, DESCRIPTION, SPECIFICATION, MAKER_PART_NO, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE= 'M104' AND CODE = MAKER_CODE) AS MAKER_NAME, MIN_ORDER_QTY, PUR_UNIT_QTY, UNIT_MEASURE, ITEM_QTY, CASE WHEN AGENT_TYPE_NAME = '신규' THEN 0 ELSE RE_LIST_PRICE END AS RE_LIST_PRICE, PO_CNT, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ09' AND CODE = PROCESS_TYPE) AS PROCESS_TYPE_NAME, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ10' AND CODE = PARCEL_YN) AS PARCEL_YN_NAME, PROCESS_TYPE, PARCEL_YN, DECODE(PROCESS_TYPE,'0', (SELECT ADDRESS_LOC FROM ICOMCMPY WHERE COM_CODE = BUYER), (SELECT ADDRESS_LOC FROM ICOMCMPY WHERE COM_CODE = X.WAREHOUSE_CODE AND STATUS <> 'D')) AS DELY_TEXT, (SELECT MIN(USER_NAME_LOC) FROM ICOMLUSR WHERE LEGACY_USER_ID = AGENT_MNG_USER_ID) AS AGENT_MNG_USER_NAME, AGENT_MNG_USER_ID, ITEM_TYPE, AGENT_DESCRIPTION, AGENT_SPECIFICATION, AGENT_MAKER_PART_NO, NVL((SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE= 'M104' AND CODE = AGENT_MAKER_CODE),AGENT_MAKER_CODE) AS AGENT_MAKER_NAME, AGENT_MAKER_CODE, AGENT_MIN_ORDER_QTY, AGENT_PUR_UNIT_QTY, AGENT_UNIT_MEASURE, AGENT_PROCESS_TYPE, AGENT_PARCEL_YN, CASE WHEN AGENT_TYPE_NAME = '신규' THEN CASE WHEN STATUS = 'K1' THEN 0 ELSE CH_LIST_PRICE END ELSE CH_LIST_PRICE END AS CH_LIST_PRICE, BUY_CLOSE_DATE, DELIVERY_LT, DELIVERY_LT AS DB_DELIVERY_LT, AGENT_REMARK, MAKER_CODE FROM ( SELECT STATUS, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'BURQ03' AND CODE = AGENT_TYPE) AS AGENT_TYPE_NAME, BURQ_RFQ_NO, PROJECT_NAME, DECODE( PROJECT_UNIT, 'B', (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = BUYER), (SELECT COMORG_NAME FROM BYCAORGL WHERE COMORG_CODE = BYIT_COMORG_CODE)) AS BUYER_NAME, ATOS_DATE, ATOS_END_DATE, NVL(SM_DESCRIPTION,KEP_DESCRIPTION) AS DESCRIPTION, NVL(SM_SPECIFICATION,KEP_SPECIFICATION) AS SPECIFICATION, NVL(SM_MAKER_PART_NO,KEP_MAKER_PART_NO) AS MAKER_PART_NO, NVL(SM_MAKER_CODE,KEP_MAKER_CODE) AS MAKER_CODE, NVL(SM_MIN_ORDER_QTY,KEP_MIN_ORDER_QTY) AS MIN_ORDER_QTY, NVL(SM_PUR_UNIT_QTY,KEP_PUR_UNIT_QTY) AS PUR_UNIT_QTY, NVL(SM_UNIT_MEASURE,KEP_UNIT_MEASURE) AS UNIT_MEASURE, (SELECT ITEM_QTY FROM KEP_BURQ_ITEM ITM WHERE RFQ.BURQ_NO = ITM.BURQ_NO AND RFQ.ITEM_KEY_ID = ITM.ITEM_KEY_ID) AS ITEM_QTY, (SELECT RE_LIST_PRICE FROM KEP_BURQ_ITEM ITM WHERE RFQ.BURQ_NO = ITM.BURQ_NO AND RFQ.ITEM_KEY_ID = ITM.ITEM_KEY_ID) AS RE_LIST_PRICE, (SELECT PO_CNT FROM KEP_BURQ_ITEM ITM WHERE RFQ.BURQ_NO = ITM.BURQ_NO AND RFQ.ITEM_KEY_ID = ITM.ITEM_KEY_ID) AS PO_CNT, SM_PROCESS_TYPE AS PROCESS_TYPE, SM_PARCEL_YN AS PARCEL_YN, SM_WAREHOUSE_CODE AS WAREHOUSE_CODE, DECODE( PROJECT_UNIT, 'B', BUYER, BYIT_COMORG_CODE ) AS BUYER, (SELECT AGENT_MNG_USER_ID FROM KEP_BURQ_ITEM ITEM WHERE ITEM.BURQ_NO = RFQ.BURQ_NO AND RFQ.ITEM_KEY_ID = ITEM.ITEM_KEY_ID) AS AGENT_MNG_USER_ID, NVL(ITEM_TYPE,'B') AS ITEM_TYPE, AGENT_DESCRIPTION, AGENT_SPECIFICATION, AGENT_MAKER_PART_NO, AGENT_MAKER_CODE, AGENT_MIN_ORDER_QTY, AGENT_PUR_UNIT_QTY, AGENT_UNIT_MEASURE, AGENT_PROCESS_TYPE, AGENT_PARCEL_YN, CH_LIST_PRICE, BUY_CLOSE_DATE, AGENT_REMARK, DELIVERY_LT FROM KEP_BURQ_RFQ RFQ, KEP_BURQ_MNG MNG WHERE RFQ.BURQ_NO = MNG.BURQ_NO AND RFQ.STATUS IN ( 'K1','S1' ) AND RFQ.BURQ_NO = #{st_burq_no} AND RFQ.AGENT = #{COM_CODE}
AND RFQ.AGENT_TYPE = #{st_agent_type}
AND RFQ.STATUS = #{st_sourcing_status}
) X WHERE 1=1
AND X.BUYER_NAME LIKE '%'||UPPER(#{st_buyer_name})||'%'
AND X.MAKER_NAME LIKE '%'||UPPER(#{st_maker_name})||'%'
AND X.BURQ_RFQ_NO IN
#{burq_rfq_no}
AND X.DESCRIPTION LIKE '%'||UPPER(#{st_description})||'%'
AND X.SPECIFICATION LIKE '%'||UPPER(#{st_specification})||'%'
AND X.MAKER_PART_NO LIKE '%'||UPPER(#{st_model_no})||'%'

mapper.update:

/*updateSellerSelProject*/
UPDATE	KEP_BURQ_MNG
SET		PROJECT_STATUS = 'C'
WHERE	BURQ_NO IN (
	SELECT BURQ_NO 
	FROM KEP_BURQ_RFQ
	WHERE	AGENT = #{COM_CODE}
)
AND	RFQ_END_DATE < SYSDATE
AND PROJECT_STATUS = 'B'


/*giveUpSellerMpRqBulkQuotationReq*/
UPDATE	KEP_BURQ_RFQ
SET		STATUS = 'S2',
		AGENT_REMARK = #{st_remark},	
		CHANGE_DATE = SYSDATE,
		CHANGE_USER_ID = #{USER_ID}
WHERE	1=1
AND		BURQ_NO = #{st_burq_no}
AND		AGENT = #{COM_CODE}
AND		BURQ_RFQ_NO = #{st_burq_rfq_no}
AND		STATUS NOT IN ( 'K4', 'S2')


/* updateBulkQuotationSamePrice */
UPDATE KEP_BURQ_RFQ RFQ
SET STATUS = 'K1',
	STOA_DATE = '',
	CHANGE_DATE = SYSDATE,
	CHANGE_USER_ID = #{USER_ID}
WHERE BURQ_NO = #{st_burq_no}
AND BURQ_RFQ_NO = #{st_burq_rfq_no}
AND AGENT = #{COM_CODE}
